class Solution {
    public TreeNode constructMaximumBinaryTree(int[] nums){
        Deque<TreeNode> stack=new ArrayDeque<>();
        for(int x: nums){
            TreeNode cur=new TreeNode(x);
            while(!stack.isEmpty() && stack.peek().val < x) cur.left=stack.pop();
            if(!stack.isEmpty()) stack.peek().right=cur;
            stack.push(cur);
        }
        return stack.isEmpty()?null:stack.peekLast();
    }
}

