class Solution:

    def constructMaximumBinaryTree(self, nums):
        stack = []
        for x in nums:
            cur = TreeNode(x)
            while stack and stack[-1].val < x:
                cur.left = stack.pop()
            if stack:
                stack[-1].right = cur
            stack.append(cur)
        return stack[0] if stack else None

def ser(root):
    if root is None:
        return []
    q = [root]
    out = []
    while q:
        n = q.pop(0)
        if n is None:
            out.append(None)
        else:
            out.append(n.val)
            q.append(n.left)
            q.append(n.right)
    while out and out[-1] is None:
        out.pop()
    return out
